<script>
  import { randomString } from '@splendidlabz/utils/dom'
  import { useActions } from '../../../actions/use-actions'
  import { init } from '../../../utils'
  import FieldMeta from '../FieldMeta.svelte'
  import { autocompleteInput } from './autocomplete.svelte.js'
  import Chips from './Chips.svelte'
  import { comboboxInput, getCombobox } from './combobox.svelte.js'
  import { toSelectedOptions } from './select.svelte.js'

  /**
   * @import { Snippet } from 'svelte'
   * @import { SelectedOption, SelectEntry } from './select.svelte.js'
   */

  /**
   * @typedef {object} AutocompleteProps
   * @property {string} name Name the selection submits under
   * @property {string} target Id of the options
   * @property {SelectEntry | SelectEntry[] | null} [selected] One entry, or an array with `multiple`. Bindable.
   * @property {string} [value] Typed text, bindable
   * @property {HTMLInputElement | null} [ref]
   * @property {boolean} [multiple] Let more than one option be selected
   * @property {number} [max] Most options a multi select takes
   * @property {boolean} [creatable] Accept text that matches no option
   * @property {(text: string) => string} [onCreateValue] Value for created text
   * @property {boolean} [caseSensitive] Match case while filtering and creating
   * @property {string | string[]} [matchBy] Keys typing matches against
   * @property {(query: string) => Promise<any[]>} [search] Fetches options as someone types
   * @property {number} [debounceMs] Wait before searching
   * @property {(item: any) => void} [onselect] Receives the item, or the option element
   * @property {boolean} [openOnFocus] Open the options on focus
   * @property {boolean} [loop] Wrap past either end
   * @property {string} [id]
   * @property {string} [label]
   * @property {boolean} [labelVisible]
   * @property {string | null} [hint]
   * @property {string | null} [error]
   * @property {boolean | null} [disabled]
   * @property {boolean | null} [readonly]
   * @property {string} [class]
   * @property {string} [style]
   * @property {string} [labelClass]
   * @property {string} [hintClass]
   * @property {string} [errorClass]
   * @property {string} [inputGroupClass]
   * @property {string} [fieldClass]
   * @property {string} [chipsClass]
   * @property {Snippet<[SelectedOption]>} [chip] Replaces a chip's label
   * @property {{ fn: Function, props?: any }[]} [actions] Actions run on the input
   */

  /** @type {AutocompleteProps & Record<string, any>} */
  let {
    value = $bindable(''),
    selected = $bindable(),
    ref = $bindable(null),
    // Classes
    class: klass,
    style,
    labelClass,
    hintClass,
    errorClass,
    inputGroupClass,
    fieldClass,
    chipsClass,
    // Slots
    chip,
    // Options and props
    id = randomString(8),
    name,
    target,
    label = '',
    labelVisible = true,
    hint = null,
    error = null,
    disabled = null,
    readonly = null,
    multiple = false,
    max,
    creatable = false,
    caseSensitive = false,
    matchBy,
    onCreateValue,
    openOnFocus = true,
    search,
    debounceMs,
    onselect,
    loop = true,
    actions = [],
    ...rest
  } = $props()

  init(() => {
    if (!name) throw new Error('Autocomplete requires a name')
    if (!target) throw new Error('Autocomplete requires a target')

    // A single select shows its selection as the input's text
    if (!multiple) value = toSelectedOptions(selected)[0]?.label ?? ''
  })

  const combobox = $derived(getCombobox(target))
  const selectedOptions = $derived(
    combobox?.state.selected ?? toSelectedOptions(selected),
  )

  // A single selection is the input's text, so only a multi select shows chips
  const chips = $derived(multiple ? selectedOptions : [])

  // A multi select submits an array, the way NativeSelect does
  const hiddenName = $derived(multiple ? `${name}[]` : name)

  // Only a selection passed in can go over the cap, since the field refuses the option past it
  const maxError = $derived(
    max && selectedOptions.length > max
      ? `Choose no more than ${max} option${max === 1 ? '' : 's'}.`
      : null,
  )
  const fieldError = $derived(error ?? maxError)

  // IDs for aria-describedby
  const hintId = $derived(hint ? id + '-hint' : '')
  const errorId = $derived(id + '-error')
  const describedBy = $derived(`${hintId} ${errorId}`.trim() || null)
</script>

<div
  {style}
  class="input-container combobox autocomplete {klass}"
  class:disabled
  class:readonly
>
  <FieldMeta
    {id}
    error={fieldError}
    {errorClass}
    {hint}
    {hintClass}
    {label}
    {labelClass}
    {labelVisible}
  />

  <div class="input-group {inputGroupClass}">
    <Chips
      class={chipsClass}
      {chip}
      disabled={disabled || readonly}
      selected={chips}
      {target}
    />

    <input
      {...rest}
      bind:this={ref}
      {id}
      class="input {fieldClass}"
      aria-autocomplete="list"
      aria-controls="{target}-listbox"
      aria-describedby={describedBy}
      aria-expanded="false"
      aria-invalid={fieldError ? 'true' : null}
      aria-label={!labelVisible && label ? label : null}
      autocomplete="off"
      disabled={disabled || readonly}
      role="combobox"
      {target}
      type="text"
      bind:value
      use:useActions={[
        {
          fn: comboboxInput,
          props: {
            options: {
              loop,
              onselectedchange:
                /** @param {SelectedOption | SelectedOption[] | null} next */ next =>
                  (selected = next),
            },
          },
        },
        {
          fn: autocompleteInput,
          props: {
            options: {
              search,
              debounceMs,
              onselect,
              multiple,
              max,
              creatable,
              caseSensitive,
              matchBy,
              onCreateValue,
              openOnFocus,
              selected,
            },
          },
        },
        ...actions,
      ]}
    />
  </div>

  {#each selectedOptions as option (option.value)}
    <input name={hiddenName} {disabled} type="hidden" value={option.value} />
  {/each}
</div>
